/**
 * @description Validiert und normalisiert die Formulardaten von request.html.
 *              Begrenzt Laengen, prueft E-Mail-Format und Honeypot und
 *              baut den KI-Input im selben Format wie der E-Mail-Collector.
 * @input  $json.body { name, email, subject, message, website }
 * @output { valid, error, fromName, fromEmail, subject, plainBody, aiInputText, safe* }
 */
const b = $json.body || $json || {};
const clean = (v, max) => String(v == null ? '' : v).replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '').trim().slice(0, max);
const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');

const fromName = clean(b.name, 80);
const fromEmail = clean(b.email, 120).toLowerCase();
const subject = clean(b.subject, 120);
const plainBody = clean(b.message, 4000);
const honeypot = clean(b.website, 200);

let error = '';
if (honeypot) error = 'bot';
else if (fromName.length < 2) error = 'name';
else if (!/^[^\s@<>"']+@[^\s@<>"']+\.[^\s@<>"']{2,}$/.test(fromEmail)) error = 'email';
else if (subject.length < 3) error = 'subject';
else if (plainBody.length < 10) error = 'message';
else if (fromEmail === 'r.neuberger@newmountains.it') error = 'email';

return {
  json: {
    valid: !error,
    error,
    fromName,
    fromEmail,
    subject,
    plainBody,
    safeName: esc(fromName),
    safeSubject: esc(subject),
    safeBody: esc(plainBody).replace(/\n/g, '<br>'),
    receivedAt: new Date().toISOString(),
    aiInputText: 'Betreff: ' + subject + '\n\nAbsender: ' + fromName + ' <' + fromEmail + '>\n\nNachricht:\n' + plainBody,
  },
};

/**
 * @description Baut fuer Limit- und Fehlerfall zwei Mails:
 *              1) Kopie der Anfrage fuer den Ordner "Zu bearbeiten" (Team)
 *              2) Hinweis an den Absender (Limit erreicht bzw. "wir melden uns")
 * @input  "Validate Request" + Herkunft ($json.count vorhanden = Limit)
 * @output { inboxCopy, senderReply, status }
 */
const r = $('Validate Request').first().json;
const isLimit = $json && typeof $json.count !== 'undefined' && Number($json.count) >= 10;
const wrap = (c) => '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="#eef2f7" style="background:#eef2f7;"><tr><td align="center" style="padding:20px 10px;"><table role="presentation" width="680" cellpadding="0" cellspacing="0" border="0" style="width:680px;max-width:100%;background:#ffffff;border:1px solid #e2e8f0;border-radius:12px;"><tr><td bgcolor="#001860" style="background:#001860;padding:16px 24px;border-radius:12px 12px 0 0;"><img src="https://newmountains.it/wp-content/uploads/2026/11/brand/nmit-mail-logo-weiss.png" alt="Newmountains.IT" width="144" height="34" style="display:block;width:144px;height:34px;border:0;"></td></tr><tr><td bgcolor="#8F35EE" style="background:#8F35EE;height:4px;line-height:4px;font-size:0;">&nbsp;</td></tr><tr><td style="padding:22px 24px;font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.6;color:#0f172a;">' + c + '</td></tr><tr><td style="padding:12px 24px 18px;border-top:1px solid #e2e8f0;font-family:Arial,Helvetica,sans-serif;font-size:11px;line-height:1.5;color:#64748b;">Newmountains.IT &middot; Oberndorferstra&szlig;e 22 &middot; 84032 Landshut &middot; <a href="https://newmountains.it/" style="color:#1273b8;text-decoration:none;">newmountains.it</a></td></tr></table></td></tr></table>';

const inboxCopy = {
  subject: '[Web-Anfrage] ' + r.subject,
  body: { contentType: 'HTML', content: '<p><strong>Web-Formular (' + (isLimit ? 'Tageslimit erreicht' : 'Verarbeitungsfehler') + ')</strong></p><p>Von: ' + r.safeName + ' &lt;' + r.fromEmail + '&gt;<br>Eingang: ' + r.receivedAt + '</p><p><strong>' + r.safeSubject + '</strong></p><p>' + r.safeBody + '</p>' },
  toRecipients: [{ emailAddress: { address: 'R.Neuberger@newmountains.it' } }],
  replyTo: [{ emailAddress: { address: r.fromEmail, name: r.fromName } }],
};

const text = isLimit
  ? '<p>vielen Dank fuer Ihre Anfrage. Aus Gruenden der Kostenkontrolle ist unsere automatisierte KI-Verarbeitung auf <strong>10 Anfragen pro Tag</strong> limitiert - dieses Tageslimit ist heute bereits erreicht.</p><p>Keine Sorge: Ihre Anfrage ist bei uns angekommen und wird vom Team manuell gesichtet. Sie erhalten dann ein Update.</p>'
  : '<p>vielen Dank fuer Ihre Anfrage. Wir haben sie erhalten - unsere automatisierte Verarbeitung konnte sie aktuell nicht abschliessen, aber das Team wurde informiert und sichtet die Anfrage zeitnah manuell.</p>';

const senderReply = {
  message: {
    subject: 'Ihre Anfrage "' + r.subject + '" - ' + (isLimit ? 'Tageslimit erreicht' : 'wir melden uns'),
    body: { contentType: 'HTML', content: wrap('<p>Hallo ' + r.safeName + ',</p>' + text + '<p>Beste Gruesse<br>Das Join-Team</p>') },
    toRecipients: [{ emailAddress: { address: r.fromEmail } }],
  },
  saveToSentItems: true,
};

return [{ json: { inboxCopy, senderReply, status: isLimit ? 'limit' : 'manual' } }];

/**
 * @description Baut das Firebase-Task-Objekt aus KI-Antwort + Formulardaten.
 *              Gleiches Datenmodell wie der E-Mail-Collector (status=triage,
 *              creator.type=external, aiGenerated=true) plus Bestaetigungsmail.
 * @input  OpenAI-Antwort, "Validate Request"
 * @output { payload, confirmationMail }
 */
const aiResponse = $input.first().json;
const r = $('Validate Request').first().json;

let ai = aiResponse?.output?.[0]?.content?.[0]?.text;
if (typeof ai === 'string') {
  try { ai = JSON.parse(ai); } catch (_e) { ai = {}; }
}
ai = ai || {};

const title = String((ai.title && ai.title.trim()) || r.subject).slice(0, 80);
const payload = {
  title,
  description: (ai.description || r.plainBody) + '\n\n---\nDieses Ticket wurde KI-generiert basierend auf einer Web-Formular-Anfrage von ' + r.fromEmail,
  dueDate: /^\d{4}-\d{2}-\d{2}$/.test(ai.dueDate || '') ? ai.dueDate : '',
  priority: ['Urgent', 'Medium', 'Low'].includes(ai.priority) ? ai.priority : 'Medium',
  category: ['Technical Tasks', 'User Story'].includes(ai.category) ? ai.category : 'User Story',
  assignedTo: [],
  subtasks: [],
  status: 'triage',
  creator: { email: r.fromEmail, name: r.fromName, type: 'external' },
  aiGenerated: true,
  source: 'web-form',
  createdAt: new Date().toISOString(),
};

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const wrap = (c) => '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="#eef2f7" style="background:#eef2f7;"><tr><td align="center" style="padding:20px 10px;"><table role="presentation" width="680" cellpadding="0" cellspacing="0" border="0" style="width:680px;max-width:100%;background:#ffffff;border:1px solid #e2e8f0;border-radius:12px;"><tr><td bgcolor="#001860" style="background:#001860;padding:16px 24px;border-radius:12px 12px 0 0;"><img src="https://newmountains.it/wp-content/uploads/2026/11/brand/nmit-mail-logo-weiss.png" alt="Newmountains.IT" width="144" height="34" style="display:block;width:144px;height:34px;border:0;"></td></tr><tr><td bgcolor="#8F35EE" style="background:#8F35EE;height:4px;line-height:4px;font-size:0;">&nbsp;</td></tr><tr><td style="padding:22px 24px;font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.6;color:#0f172a;">' + c + '</td></tr><tr><td style="padding:12px 24px 18px;border-top:1px solid #e2e8f0;font-family:Arial,Helvetica,sans-serif;font-size:11px;line-height:1.5;color:#64748b;">Newmountains.IT &middot; Oberndorferstra&szlig;e 22 &middot; 84032 Landshut &middot; <a href="https://newmountains.it/" style="color:#1273b8;text-decoration:none;">newmountains.it</a></td></tr></table></td></tr></table>';

const confirmationMail = {
  message: {
    subject: 'Bestaetigung: Ihr Feature Request "' + title + '"',
    body: { contentType: 'HTML', content: wrap('<p>Hallo ' + r.safeName + ',</p><p>vielen Dank fuer Ihre Anfrage. Wir haben ein Ticket in unserem Kanban-Board angelegt:</p><p><strong>' + esc(title) + '</strong></p><p>Sie werden ueber Statusaenderungen automatisch per E-Mail benachrichtigt.</p><p>Beste Gruesse<br>Das Join-Team</p>') },
    toRecipients: [{ emailAddress: { address: r.fromEmail } }],
  },
  saveToSentItems: true,
};

return { json: { payload, confirmationMail } };
